"use strict";
const byId = id => document.getElementById(id);
const courseById = id => COURSES.find(c=>c.id===id);
const targetById = id => TARGETS.find(t=>t.id===id);
const state={selected:new Set(["math151","cisc187","cisc246"]),targets:new Set(TARGETS.map(t=>t.id)),focus:"ucsd",scenario:"balanced",query:"",category:"All"};
const dialog=byId("detail-dialog");
let toastTimer;
function notify(message){byId("toast").textContent=message;byId("toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId("toast").classList.remove("visible"),3500)}
const link=(url,label)=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+' ↗</a>';
function included(){return COURSES.filter(c=>state.selected.has(c.id))}
function activeTargets(){return TARGETS.filter(t=>state.targets.has(t.id))}
function benefits(c){return c.targets.filter(t=>state.targets.has(t))}
function stats(){const selected=included();return{units:selected.reduce((n,c)=>n+c.units,0),contributions:selected.reduce((n,c)=>n+benefits(c).length,0),helped:activeTargets().filter(t=>selected.some(c=>c.targets.includes(t.id))).length,courses:selected.length}}
function progress(t){const done=COURSES.filter(c=>c.completed&&c.targets.includes(t.id)).length;const next=included().filter(c=>c.targets.includes(t.id)).length;return{done,next,total:t.total}}
function summary(){const s=stats();return "TRANSFER COPILOT — SAMPLE PLAN\nFictional student: Jordan Lee, San Diego Mesa College\nComputer Science · Spring 2027 planning\n\n"+included().map(c=>c.code+" — "+c.title+" ("+c.units+" units)").join("\n")+"\nTotal: "+s.units+" units\n\n"+activeTargets().map(t=>{const p=progress(t);return t.name+": "+p.done+" completed + "+p.next+" planned / "+p.total+" illustrative items"}).join("\n")+"\n\nPUBLIC FACTS: Mesa course names and units from the 2026–27 catalog. UCSD department table lists Mesa MATH 150 → MATH 20A and MATH 151 → MATH 20B (row dated June 16, 2026).\nDEMO ASSUMPTIONS: Student, other mappings, checklist totals, progress, and course priorities. No admission or eligibility assessment. Spring 2027 sections, seats and prerequisites must be checked separately. ASSIST access pending.\n\nOfficial class search: "+SOURCES.classSearch+"\nCatalog: "+SOURCES.catalog+"\nUCSD math: "+SOURCES.ucsdMath}
function showDialog(title,html){byId("dialog-title").textContent=title;byId("dialog-body").innerHTML=html;if(!dialog.open)dialog.showModal()}
function showSources(){showDialog("Know what’s behind the plan",'<div class="evidence-banner"><span class="evidence-icon">✓</span><div><strong>Public facts, clearly separated from sample logic.</strong><p>Research snapshot · September 13, 2026</p></div></div><div class="source-block"><span class="source-pill verified">Official college facts</span><h3>7 San Diego Mesa courses</h3><p>Course codes, titles, units and general UC/CSU transferability come from the 2026–27 Mesa catalog. General transferability does not mean a course satisfies a particular major.</p>'+link(SOURCES.catalog,"View Mesa catalog")+'</div><div class="source-block"><span class="source-pill verified">Official department table</span><h3>Two UCSD calculus relationships</h3><p>Mesa MATH 150 → UCSD MATH 20A; Mesa MATH 151 → UCSD MATH 20B. The department table’s Mesa row is dated June 16, 2026. Applicability to an individual record still requires official review.</p>'+link(SOURCES.ucsdMath,"View UCSD equivalency table")+'<p>'+link(SOURCES.ucsdPrep,"UCSD major preparation")+'</p></div><div class="source-block"><span class="source-pill">Illustrative—not verified</span><h3>Student, other mappings & progress</h3><p>Jordan is fictional. All other campus matches, checklist denominators, priorities, overlap scores and scenarios are demo assumptions. CSU source links provide context, not verification of those mappings.</p>'+link(SOURCES.sdsuPathway,"SDSU–SDCCD pathway")+'<p>'+link(SOURCES.csusm,"Historical CSUSM CS worksheet (2023–24)")+'</p></div><div class="source-block"><span class="source-pill amber">Not connected</span><h3>ASSIST & live availability</h3><p>The project owner has submitted an ASSIST API request. No ASSIST data was scraped or integrated. Spring 2027 offerings, seat counts, local prerequisites and time conflicts are not verified. No enrollment action is taken.</p>'+link(SOURCES.assistTerms,"ASSIST reuse terms")+'<p>'+link(SOURCES.classSearch,"Check live SDCCD classes")+'</p></div><p class="scope-note">This POC is not a complete transfer, GPA, GE, Cal-GETC, TAG, ADT or admissions audit. No real student records, accounts, paid services or live AI are used.</p>')}
function showTarget(id){const t=targetById(id);state.focus=id;renderTargets();const p=progress(t);const mapped=COURSES.filter(c=>c.targets.includes(id)&&(c.completed||state.selected.has(c.id)));showDialog(t.name+" · Sample pathway",'<div class="dialog-summary"><strong>'+p.done+' <span>completed</span></strong><span>+</span><strong>'+p.next+' <span>planned</span></strong><span>/ '+p.total+' demo items</span></div><p>These counts illustrate the experience; they are not verified major-completion totals.</p><label class="include-target"><input type="checkbox" data-include-target="'+id+'" '+(state.targets.has(id)?"checked":"")+'> Include this campus in my comparison</label><div class="checklist">'+mapped.map(c=>'<div><span class="check-status '+(c.completed?"done":"")+'">'+(c.completed?"✓":"◷")+'</span><span><strong>'+c.code+'</strong> '+c.topic+'</span><span class="mini-status">'+(c.completed?"Sample completed":"Planned")+'</span></div>').join("")+'</div><div class="source-block"><h3>What the official source tells us</h3><p>'+t.note+'</p>'+link(SOURCES[t.source],"Read the official source")+'</div><p class="scope-note">Other required coursework and policies are not represented by this small demo checklist. Review the full applicable agreement with a counselor.</p>')}
function showCourse(id){const c=courseById(id);showDialog(c.code+" · Course details",'<span class="source-pill verified">Official Mesa catalog · 2026–27</span><h3 class="detail-title">'+c.title+'</h3><div class="detail-facts"><span><strong>'+c.units+'</strong> units</span><span>San Diego Mesa</span><span>UC / CSU transferable*</span></div><p>'+(c.reason||"This course appears in Jordan’s fictional completed history. The course itself is real; the student's completion is not.")+'</p><div class="source-block"><h3>Evidence</h3><p>'+link(c.source,"Mesa course page")+' · '+link(SOURCES.catalog,"Catalog, printed page "+c.page)+'</p>'+(c.verified?'<p><strong>Published relationship:</strong> '+c.code+' → '+c.verified+'. Department table row dated June 16, 2026.</p>'+link(SOURCES.ucsdMath,"UCSD math source"):'<p>No specific university equivalency is verified for this course in the demo.</p>')+'</div><div class="source-block"><h3>Before choosing a section</h3><p>Spring 2027 availability, meeting times, seats and prerequisite clearance are unknown. Check them in the official search and with the college.</p>'+link(SOURCES.classSearch,"Search current SDCCD classes")+'</div><p class="scope-note">*General UC/CSU transferability is not proof of major equivalency, eligibility, or guaranteed credit acceptance.</p>')}
function showShare(parent=false){const s=stats();showDialog(parent?"Family & counselor view":"Share a clear next step",'<span class="source-pill">Fictional student · Read-only summary</span><div class="share-heading"><span class="avatar">JL</span><div><h3>Jordan’s next-semester plan</h3><p>San Diego Mesa → Computer Science</p></div></div><div class="summary-tiles"><div><strong>'+s.units+'</strong><span>planned units</span></div><div><strong>'+s.courses+'</strong><span>courses</span></div><div><strong>'+activeTargets().length+'</strong><span>targets compared</span></div></div><div class="summary-courses">'+included().map(c=>'<div><strong>'+c.code+'</strong><span>'+c.title+'</span><span>'+c.units+' units</span></div>').join("")+'</div><div class="summary-caution"><strong>Questions for the counselor</strong><p>Which mappings apply to the student’s agreement year? Are local prerequisites cleared? What major, GE, unit and admission checks are still missing?</p></div><div class="dialog-actions"><button class="button navy" data-action="copy-summary">Copy summary</button><button class="button outline" data-action="download-summary">Download summary</button><button class="button subtle" data-action="copy-link">Copy demo link</button></div><p class="scope-note">Sharing copies this fictional sample only. There is no account, stored transcript, live parent access, or real counselor review.</p>')}
function showWhy(){const s=stats();showDialog("Why this plan?",'<span class="source-pill">Transparent demo logic · No live AI</span><h3 class="detail-title">'+s.courses+' courses. '+s.helped+' sample pathways advanced.</h3><p>The demo counts each course’s contribution to the selected target checklists, then shows the unit load alongside it. It does not predict admission or optimize a real academic plan.</p><div class="checklist">'+included().map(c=>'<div><span class="check-status">↗</span><span><strong>'+c.code+'</strong><br><small>'+benefits(c).map(id=>targetById(id).short).join(" · ")+' — sample contributions</small></span><strong>'+c.units+' units</strong></div>').join("")+'</div><div class="source-block"><h3>Transfer Efficiency Score</h3><p>For this POC, the displayed efficiency measure is <strong>'+s.contributions+' course–target contributions across '+s.units+' units</strong>. Each selected course contributes at most once per target. It is a transparent illustration, not a validated 0–100 score.</p></div><p>Unknown prerequisites, source-year applicability, and unavailable sections are not solved by this count. Those checks remain visible below the plan.</p><button class="button outline" data-open="sources">Inspect sources & assumptions</button>')}
function setScenario(name){if(!["balanced","lighter"].includes(name))throw new Error("Unknown scenario");state.selected=new Set(name==="balanced"?["math151","cisc187","cisc246"]:["math151","cisc246"]);state.scenario=name;render();return readState()}
function setCourses(ids){if(!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.some(id=>!courseById(id)||courseById(id).completed))throw new Error("Expected unique, selectable course IDs");state.selected=new Set(ids);state.scenario="custom";render();return readState()}
function setTargets(ids){if(!Array.isArray(ids)||ids.length<1||ids.length>3||new Set(ids).size!==ids.length||ids.some(id=>!targetById(id)))throw new Error("Select one to three valid targets");state.targets=new Set(ids);render();return readState()}
function readState(){return{scenario:state.scenario,courseIds:[...state.selected],targetIds:[...state.targets],...stats(),dataMode:"fictional student; mixed official facts and illustrative mappings; not academic advice"}}
function renderTargets(){byId("target-list").innerHTML=TARGETS.map(t=>{const p=progress(t),active=state.targets.has(t.id);return'<button class="target-row '+(state.focus===t.id?"selected ":"")+(active?"":"excluded")+'" data-target="'+t.id+'" aria-label="View '+t.name+' sample pathway"><span class="campus-icon '+t.color+'">'+t.monogram+'</span><span class="target-name"><strong>'+t.name+'</strong><small>'+(active?'Sample prep: '+p.done+' done + '+p.next+' planned':'Not included in comparison')+'</small><span class="progress-track"><span class="progress-done" style="width:'+p.done/p.total*100+'%"></span><span class="progress-next" style="width:'+p.next/p.total*100+'%"></span></span></span><span class="target-value">'+(active?p.done+p.next:"—")+'<span>/ '+p.total+'</span></span><span class="chevron">↗</span></button>'}).join("");document.querySelector(".pathways .tiny-tag").textContent=activeTargets().length+" targets";document.querySelector(".pathways .muted").innerHTML='Computer Science · <button class="text-button" data-action="history">View sample coursework</button>'}
function renderCourses(){const s=stats();byId("course-content").innerHTML='<div class="course-table-wrap"><table class="course-table"><thead><tr><th scope="col">Include</th><th scope="col">Course</th><th scope="col">Units</th><th scope="col">Sample target overlap</th><th scope="col">Evidence</th></tr></thead><tbody>'+COURSES.filter(c=>!c.completed).map(c=>'<tr class="'+(state.selected.has(c.id)?"":"course-off")+'"><td><input type="checkbox" aria-label="Include '+c.code+'" data-course="'+c.id+'" '+(state.selected.has(c.id)?"checked":"")+'></td><td><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span>'+c.title+'</span></button></td><td class="unit-cell">'+c.units+'</td><td><div class="target-chips">'+benefits(c).map(id=>'<span>'+targetById(id).short+'</span>').join("")+(benefits(c).length?"":'<span class="neutral">No selected targets</span>')+'</div></td><td><button class="evidence-link" data-course-detail="'+c.id+'">'+(c.verified?'UCSD source ↗':'Demo mapping ↗')+'</button></td></tr>').join("")+'</tbody></table></div><div class="plan-total"><span><strong>'+s.courses+' courses · '+s.units+' units</strong><span class="total-caption">Candidate plan—not a confirmed schedule</span></span><button class="text-button" data-action="why">Why these courses? ↗</button></div><div class="scenario-insight"><span class="insight-symbol">↔</span><p>'+(state.scenario==="lighter"?'<strong>4 fewer units, one course deferred.</strong> CISC 187 moves out of this sample term; the illustrative checklist gains one fewer item at each selected target.':state.scenario==="balanced"?'<strong>Keep the load in view.</strong> This 11-unit sample balances calculus, programming and discrete math. Prerequisites and sections still need verification.':'<strong>Your scenario, recalculated.</strong> '+s.contributions+' sample course–target contributions across '+s.units+' units. Compare the change with the balanced plan.')+'</p><button class="text-button" data-action="why">See tradeoffs</button></div>';
byId("risk-content").innerHTML='<div class="risk-item"><span class="risk-icon">!</span><div><h3>Verify before enrolling</h3><p>'+(state.selected.has("cisc187")?'CISC 187 requires a local prerequisite check. This sample does not establish programming clearance.':'Local prerequisites and course timing still need college confirmation.')+'</p></div><button class="text-button" data-open="sources">Review</button></div><div class="risk-item"><span class="risk-icon blue">i</span><div><h3>'+(s.units>12?'Check your workload':'The rest of transfer still matters')+'</h3><p>'+(s.units>12?'This candidate plan exceeds the sample 12-unit comfort limit. Try a lighter load or remove a course.':'Major mapping, GE, unit totals, GPA and application requirements are not fully evaluated in this POC.')+'</p></div><button class="text-button" data-action="share">Prepare questions</button></div>'}
function renderExplorer(){const q=state.query.toLowerCase().trim();const list=COURSES.filter(c=>(state.category==="All"||c.category===state.category)&&(!q||(c.code+" "+c.title).toLowerCase().includes(q)));byId("explorer-results").innerHTML=list.length?list.map(c=>'<article class="explorer-card"><div class="explorer-top"><span class="source-pill">'+c.category+'</span><span class="explorer-units">'+c.units+' units</span></div><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span>'+c.title+'</span></button><div class="college-label">San Diego Mesa College · 2026–27 catalog</div><div class="availability"><span>Spring 2027 sections</span><strong>Not checked</strong></div><div class="explorer-actions">'+(c.completed?'<span class="completed-label">✓ Sample completed</span>':'<button class="button '+(state.selected.has(c.id)?"subtle":"outline")+'" data-add-course="'+c.id+'">'+(state.selected.has(c.id)?"Remove from plan":"Add to scenario")+'</button>')+link(c.source,"Course page")+'</div></article>').join(""):'<div class="empty-state"><h3>No matching courses in this sample.</h3><p>Try “calculus” or clear the filters. This demo includes 7 courses, not the full district catalog.</p><button class="button outline" data-action="clear-search">Clear filters</button></div>';byId("result-count").textContent=list.length+" of 7 sample courses"}
function render(){const s=stats();renderTargets();renderCourses();renderExplorer();byId("plan-units").textContent=s.units;byId("plan-benefit").textContent=s.helped;document.querySelector(".recommendation h2").innerHTML=state.scenario==="lighter"?"A lighter load.<br>Clearer tradeoffs.":s.courses===0?"Start with one<br>thoughtful choice.":"Build on the<br>courses you’ve started.";document.querySelector(".recommendation p").textContent=state.scenario==="lighter"?"Seven units keeps calculus and discrete math in view. See what changes when programming waits.":s.courses===0?"Add a course below to explore how it changes the sample pathways.":"Explore "+s.courses+" courses that add "+s.contributions+" illustrative course–target contributions. Keep the workload and the evidence in view.";document.querySelectorAll("[data-scenario]").forEach(b=>{b.classList.toggle("selected",b.dataset.scenario===state.scenario);b.setAttribute("aria-pressed",String(b.dataset.scenario===state.scenario))});byId("live-status").textContent=s.courses+" courses selected, "+s.units+" units, "+s.helped+" sample targets helped."}
function showHistory(){showDialog("Jordan’s sample coursework",'<span class="source-pill">Fictional history · No transcript uploaded</span><p>These three real Mesa courses are marked completed only for the demonstration. Other previous coursework, grades and units are not modeled.</p><div class="checklist">'+COURSES.filter(c=>c.completed).map(c=>'<div><span class="check-status done">✓</span><span><strong>'+c.code+'</strong><br>'+c.title+'</span><strong>'+c.units+' units</strong></div>').join("")+'</div><p>Source-year applicability, course repeats, exam credit, prerequisites and total transfer eligibility need separate review.</p>')}
document.addEventListener("click",async event=>{const b=event.target.closest("button,[data-open]");if(!b)return;
if(b.dataset.open==="sources")return showSources();
if(b.dataset.target)return showTarget(b.dataset.target);
if(b.dataset.courseDetail)return showCourse(b.dataset.courseDetail);
if(b.dataset.scenario){setScenario(b.dataset.scenario);return}
if(b.dataset.addCourse){const ids=new Set(state.selected);ids.has(b.dataset.addCourse)?ids.delete(b.dataset.addCourse):ids.add(b.dataset.addCourse);setCourses([...ids]);return notify(state.selected.has(b.dataset.addCourse)?"Course added to your sample plan":"Course removed from your sample plan")}
const action=b.dataset.action;
if(action==="why")return showWhy();
if(action==="share")return showShare();
if(action==="parent")return showShare(true);
if(action==="history")return showHistory();
if(action==="clear-search"){state.query="";state.category="All";byId("course-search").value="";byId("category-filter").value="All";return renderExplorer()}
if(action==="copy-summary"||action==="copy-link"){const text=action==="copy-summary"?summary():location.origin+location.pathname;try{await navigator.clipboard.writeText(text);notify(action==="copy-summary"?"Sample summary copied":"Demo link copied")}catch{showDialog("Copy your summary",'<p>Clipboard access is unavailable in this browser. Select and copy the text below.</p><textarea id="copy-fallback" readonly aria-label="Text to copy"></textarea>');byId("copy-fallback").value=text;byId("copy-fallback").select()}return}
if(action==="download-summary"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([summary()],{type:"text/plain;charset=utf-8"}));a.download="transfer-copilot-sample-plan.txt";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify("Sample summary downloaded")}
});
document.addEventListener("change",event=>{const el=event.target;if(el.dataset.course){const ids=new Set(state.selected);el.checked?ids.add(el.dataset.course):ids.delete(el.dataset.course);setCourses([...ids])}if(el.dataset.includeTarget){const ids=new Set(state.targets);el.checked?ids.add(el.dataset.includeTarget):ids.delete(el.dataset.includeTarget);try{setTargets([...ids]);showTarget(el.dataset.includeTarget)}catch(error){el.checked=true;notify(error.message)}}});
byId("course-search").addEventListener("input",e=>{state.query=e.target.value;renderExplorer()});
byId("category-filter").addEventListener("change",e=>{state.category=e.target.value;renderExplorer()});
byId("close-dialog").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
byId("reset").addEventListener("click",()=>{state.targets=new Set(TARGETS.map(t=>t.id));state.focus="ucsd";state.query="";state.category="All";byId("course-search").value="";byId("category-filter").value="All";setScenario("balanced");notify("Demo reset to the balanced sample plan")});
byId("share").addEventListener("click",()=>showShare());
render();
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener("pagehide",()=>lifecycle.abort(),{once:true});
const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
register({name:"read_sample_transfer_plan",title:"Read sample transfer plan",description:"Read the fictional demo plan and its current scenario, targets and totals. Not academic advice.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>readState()});
register({name:"configure_sample_scenario",title:"Choose a demo semester scenario",description:"Change the visible sample plan to balanced or lighter. Updates demo state only; no enrollment or saving.",inputSchema:{type:"object",properties:{scenario:{type:"string",enum:["balanced","lighter"]}},required:["scenario"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=="scenario"))throw new Error("Invalid scenario input");return setScenario(input.scenario)}});
register({name:"configure_sample_courses",title:"Configure sample courses",description:"Replace the current demo course selection. Only math151, cisc187, cisc246 and phys196 are selectable. No registration action.",inputSchema:{type:"object",properties:{courseIds:{type:"array",items:{type:"string",enum:["math151","cisc187","cisc246","phys196"]},uniqueItems:true}},required:["courseIds"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=="courseIds"))throw new Error("Invalid course input");return setCourses(input.courseIds)}});
}

